8115: function Read-StreamChunk {
8116:     param([string]$Path, [long]$Offset = 0, [byte[]]$Carry = @())
8117:     $r = [pscustomobject]@{ Offset = $Offset; Bytes = 0; Lines = [string[]]@(); Carry = [byte[]]@($Carry) }
8118:     if (-not $Path) { return $r }
8119:     $fs = $null
8120:     try {
8121:         $fs = New-Object IO.FileStream($Path, [IO.FileMode]::Open, [IO.FileAccess]::Read, ([IO.FileShare]::ReadWrite -bor [IO.FileShare]::Delete))
8122:         if ($fs.Length -lt $Offset) { $Offset = 0; $Carry = @() }
8123:         [void]$fs.Seek($Offset, [IO.SeekOrigin]::Begin)
8124:         $ms = New-Object IO.MemoryStream
8125:         if (@($Carry).Count -gt 0) { $ms.Write([byte[]]$Carry, 0, @($Carry).Count) }
8126:         $buf = New-Object byte[] 65536
8127:         $grown = 0
8128:         while ($true) {
8129:             $got = $fs.Read($buf, 0, $buf.Length)
8130:             if ($got -le 0) { break }
8131:             $ms.Write($buf, 0, $got)
8132:             $grown += $got
8133:         }
8134:         $all = $ms.ToArray()
8135:         $lines = New-Object System.Collections.Generic.List[string]
8136:         $start = 0
8137:         for ($i = 0; $i -lt $all.Length; $i++) {
8138:             if ($all[$i] -eq 10) {
8139:                 $lines.Add($script:Utf8NoBom.GetString($all, $start, $i - $start).TrimEnd("`r"))
8140:                 $start = $i + 1
8141:             }
8142:         }
8143:         $rest = New-Object byte[] ($all.Length - $start)
8144:         if ($rest.Length -gt 0) { [Array]::Copy($all, $start, $rest, 0, $rest.Length) }
8145:         $r.Offset = $Offset + $grown
8146:         $r.Bytes = $grown
8147:         $r.Lines = [string[]]$lines.ToArray()
8148:         $r.Carry = $rest
8149:     } catch { } finally { if ($fs) { $fs.Dispose() } }
8150:     return $r
